/bin/bash -lc "node --input-type=module <<'JS'
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';
import net from 'node:net';
const directory = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const socket = net.createServer().listen(0, '127.0.0.1');
await once(socket, 'listening');
const port = socket.address().port;
await new Promise(resolve => socket.close(resolve));
const child = spawn('npm', ['start'], { detached: true, env: { ...process.env, PORT: String(port), DB_PATH: join(directory, 'launch.sqlite') }, stdio: ['ignore', 'pipe', 'pipe'] });
try {
  let healthy = false;
  for (let attempt = 0; attempt < 100; attempt++) {
    try {
      const response = await fetch("'`http://127.0.0.1:${port}/health`);
      if (response.status === 200 && JSON.stringify(await response.json()) === '"'{\"status\":\"ok\"}') { healthy = true; break; }
    } catch {}
    await new Promise(resolve => setTimeout(resolve, 25));
  }
  if ("'!healthy) throw new Error('"'npm start health check failed');
  console.log('npm start: HTTP 200, {\"status\":\"ok\"}');
} finally {
  const exited = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  await rm(directory, { recursive: true, force: true });
}
